// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this) && caller != address(0));
        vm.prank(caller);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertTrue(ok == false && c.owner() == address(0));
    }
}
